import json,re,chess,random
def run_solution(fen):
    for pattern, repl in json.load(open("/app/re.json")):
        fen=re.sub(pattern,repl,fen)
    return [" ".join(x.split(" ")[:-2]) for x in fen.split("\n")]
random.seed(0)
fails=0
total=0
for trial in range(30):
    b=chess.Board()
    for _ in range(60):
        if b.is_game_over():
            break
        if b.turn==chess.WHITE:
            fen=b.fen()
            ours=set(run_solution(fen))
            exp=set()
            for m in b.legal_moves:
                if m.promotion and m.promotion!=chess.QUEEN:
                    continue
                c=b.copy()
                c.push(m)
                exp.add(" ".join(c.fen().split(" ")[:-2]))
            total+=1
            bad=False
            if len(ours)!=len(exp):
                bad=True
            else:
                for x in ours:
                    if x not in exp and x.rpartition(" ")[0]+" -" not in exp:
                        bad=True
                        break
            if bad:
                print("FAIL",fen,len(ours),len(exp))
                print("missing",exp-ours)
                print("extra",ours-exp)

